import { test } from "node:test";
import http from "node:http";
import type { Socket } from "node:net";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { execSync, spawnSync } from "node:child_process";
import { trackResource } from "./leak_registry.js";

export type Reply =
  /** `truncated`: the reply hits the output limit (finish_reason=length) partway through its tool calls' arguments. */
  | { kind: "tools"; calls: Array<{ name: string; args: unknown; id?: string }>; content?: string; delayMs?: number; truncated?: boolean }
  /** `chunks`: stream the text in these pieces, `gapMs` apart (the default sends it in one delta). `truncated`: finish_reason=length. */
  | { kind: "text"; content: string; delayMs?: number; chunks?: string[]; gapMs?: number; truncated?: boolean }
  | { kind: "http"; status: number; body?: string; delayMs?: number };

export interface Gateway {
  url: string;
  requests: unknown[];
  /** Bodies of /tokenize requests (only with `options.tokenize`). */
  tokenizeRequests: any[];
  /** Number of GET /models requests served. */
  modelRequests: number;
  /** Authorization headers seen, per path kind. */
  authSeen: Array<{ path: string; authorization?: string }>;
  close(): Promise<void>;
}

/** Optional gateway capabilities (homelab-ai contract shape): catalog entries, request counting, admission headers. */
export interface GatewayOptions {
  /** `data` entries for GET /models (default: [{ id: "m" }]). Called per request, so tests can change capacity. */
  models?: () => any[];
  /** Answer to POST /tokenize; absent: 404. */
  tokenize?: (body: any, n: number) => { status: number; body: unknown; delayMs?: number };
  /** Response headers for the n-th chat request (e.g. X-AIHost-* admission headers). */
  headers?: (n: number, body: any) => Record<string, string>;
}

function sse(obj: unknown): string {
  return `data: ${JSON.stringify(obj)}\n\n`;
}

/** A tool call's arguments as sent: whole, or cut off partway like a reply that hit the output limit. */
function wireArguments(args: unknown, truncated?: boolean): string {
  const json = JSON.stringify(args);
  return truncated ? json.slice(0, Math.max(1, Math.floor(json.length / 2))) : json;
}

function finishReason(r: Extract<Reply, { kind: "tools" | "text" }>): string {
  return r.truncated ? "length" : r.kind === "tools" ? "tool_calls" : "stop";
}

function streamBody(r: Extract<Reply, { kind: "tools" | "text" }>): string {
  let out = "";
  if (r.kind === "text") out += sse({ choices: [{ index: 0, delta: { content: r.content } }] });
  else {
    if (r.content) out += sse({ choices: [{ index: 0, delta: { content: r.content } }] });
    r.calls.forEach((c, i) => {
      out += sse({ choices: [{ index: 0, delta: { tool_calls: [{ index: i, id: c.id ?? `call_${i}_${Math.random().toString(36).slice(2, 7)}`, type: "function", function: { name: c.name, arguments: wireArguments(c.args, r.truncated) } }] } }] });
    });
  }
  out += sse({ choices: [{ index: 0, delta: {}, finish_reason: finishReason(r) }] });
  return out + "data: [DONE]\n\n";
}

/** Deterministic OpenAI-compatible gateway. `script(n, body)` decides the reply to the n-th chat request (1-based). */
export async function startGateway(script: (n: number, body?: any) => Reply, options: GatewayOptions = {}): Promise<Gateway> {
  const requests: unknown[] = [];
  const tokenizeRequests: any[] = [];
  const authSeen: Array<{ path: string; authorization?: string }> = [];
  let modelRequests = 0;
  const sockets = new Set<Socket>();
  const server = http.createServer((req, res) => {
    authSeen.push({ path: req.url ?? "", authorization: req.headers.authorization });
    if (req.url?.endsWith("/models")) {
      modelRequests++;
      res.setHeader("content-type", "application/json");
      res.end(JSON.stringify({ data: options.models ? options.models() : [{ id: "m" }] }));
      return;
    }
    if (req.url?.endsWith("/tokenize")) {
      let raw = "";
      req.on("data", (c) => (raw += c));
      req.on("end", () => {
        let body: any = {};
        try { body = JSON.parse(raw); } catch {}
        tokenizeRequests.push(body);
        if (!options.tokenize) {
          res.statusCode = 404;
          res.end(JSON.stringify({ status: "not_found", message: "no tokenize" }));
          return;
        }
        const answer = options.tokenize(body, tokenizeRequests.length);
        const send = () => {
          if (res.writableEnded || res.destroyed) return;
          res.statusCode = answer.status;
          res.setHeader("content-type", "application/json");
          res.end(typeof answer.body === "string" ? answer.body : JSON.stringify(answer.body));
        };
        if (answer.delayMs) setTimeout(send, answer.delayMs); else send();
      });
      return;
    }
    let raw = "";
    req.on("data", (c) => (raw += c));
    req.on("end", () => {
      let body: any = {};
      try { body = JSON.parse(raw); } catch {}
      requests.push(body);
      const extraHeaders = options.headers ? options.headers(requests.length, body) : {};
      for (const [k, v] of Object.entries(extraHeaders)) res.setHeader(k, v);
      const r = script(requests.length, body);
      const respond = () => {
        if (res.writableEnded || res.destroyed) return;
        if (r.kind === "http") {
          res.statusCode = r.status;
          res.end(r.body ?? "{}");
        } else if (body.stream && r.kind === "text" && r.chunks?.length) {
          res.writeHead(200, { "content-type": "text/event-stream" });
          const pieces = [...r.chunks];
          const next = () => {
            if (res.writableEnded || res.destroyed) return;
            const piece = pieces.shift();
            if (piece === undefined) {
              res.end(sse({ choices: [{ index: 0, delta: {}, finish_reason: "stop" }] }) + "data: [DONE]\n\n");
              return;
            }
            res.write(sse({ choices: [{ index: 0, delta: { content: piece } }] }));
            setTimeout(next, r.gapMs ?? 50);
          };
          next();
        } else if (body.stream) {
          res.writeHead(200, { "content-type": "text/event-stream" });
          res.end(streamBody(r));
        } else {
          res.setHeader("content-type", "application/json");
          const message = r.kind === "text"
            ? { role: "assistant", content: r.content }
            : { role: "assistant", content: r.content ?? null, tool_calls: r.calls.map((c, i) => ({ id: c.id ?? `call_${i}`, type: "function", function: { name: c.name, arguments: wireArguments(c.args, r.truncated) } })) };
          res.end(JSON.stringify({ choices: [{ index: 0, message, finish_reason: r.truncated ? "length" : "stop" }] }));
        }
      };
      if (r.delayMs) setTimeout(respond, r.delayMs); else respond();
    });
  });
  server.on("connection", (s) => { sockets.add(s); s.on("close", () => sockets.delete(s)); });
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", () => resolve()));
  const port = (server.address() as any).port;
  trackResource("gateway", `scripted gateway on port ${port} not closed`, () => server.listening, () => close());
  const close = async () => {
/**
 * TI-1: what the model is actually sent. Every scenario runs the real agent against a scripted gateway and captures the
 * chat/completions bodies. Each body is reduced to a deterministic shape (roles, message kinds, tool names, tool_choice,
 * key presence; no ids, paths, hashes or prompt text) and compared with test/fixtures/request_shape/*.json.
 * NEXUS_UPDATE_SNAPSHOTS=1 rewrites the files. The invariants that matter are also asserted directly, so a blind
 * snapshot update cannot hide them.
 */
import { test, describe, before, after } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { AutonomousAgent } from "../src/agent.js";
import { DEFAULT_CONTINUATION, HarnessConfig } from "../src/types.js";
import { SessionManager } from "../src/session.js";
import { PINNED_LEDGER_PREFIX } from "../src/core/objective.js";
import { CONTENT_CALL_NOTE } from "../src/core/content_tool_call.js";
import { startGateway, makeRepo, Reply } from "./helpers/fixtures.js";

const here = path.dirname(fileURLToPath(import.meta.url));
const snapshotDir = path.join(here, "fixtures", "request_shape");

let home = "";
let previousHome: string | undefined;
before(() => {
  previousHome = process.env.HOME;
  home = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-rs-home-"));
  process.env.HOME = home;
});
after(() => {
  process.env.HOME = previousHome;
  fs.rmSync(home, { recursive: true, force: true });
});

const quiet = (agent: AutonomousAgent) => {
  (agent as any).ui = new Proxy({}, { get: () => () => {} });
  return agent;
};
const cfg = (endpoint: string, workspace: string): HarnessConfig => ({
  endpoint,
  model: "m",
  maxSteps: 30,
  temperature: 0,
  workspace,
  shell: "bash",
  approvalMode: "auto",
  fullAccess: true,
  continuation: { ...DEFAULT_CONTINUATION },
});
const write = (name: string): Reply => ({ kind: "tools", calls: [{ name: "write_file", args: { path: name, content: `${name}\n` } }] });
const text = (content: string): Reply => ({ kind: "text", content });
const contentCall: Reply = text('{"name":"write_file","arguments":{"path":"a.txt","content":"a\\n"}}');

const textOf = (m: any): string => (typeof m.content === "string" ? m.content : JSON.stringify(m.content ?? ""));

type Kind = "system-prompt" | "pinned-ledger" | "context-memory" | "retry-note" | "continuation-nudge" | "user" | "assistant-text" | "assistant-tool-calls" | "tool-result";

function kindOf(m: any, index: number): Kind {
  const body = textOf(m);
  if (m.role === "system") return body.startsWith(PINNED_LEDGER_PREFIX) ? "pinned-ledger" : body.startsWith("[Structured Context Memory") ? "context-memory" : "system-prompt";
  if (m.role === "tool") return "tool-result";
  if (m.role === "assistant") return Array.isArray(m.tool_calls) && m.tool_calls.length ? "assistant-tool-calls" : "assistant-text";
  if (body === CONTENT_CALL_NOTE) return "retry-note";
  if (body.startsWith("[Nexus continuation")) return "continuation-nudge";
  assert.ok(m.role === "user", `unexpected role ${m.role} at ${index}`);
  return "user";
}

/** Structure only: ids become ordinals and prompt text is dropped. */
function shapeOf(body: any): unknown {
  const ids = new Map<string, string>();
  const ordinal = (id: unknown) => {
    const key = String(id);
    if (!ids.has(key)) ids.set(key, `call#${ids.size + 1}`);
    return ids.get(key)!;
  };
  return {
    keys: Object.keys(body).sort(),
    stream: body.stream ?? null,
    tool_choice: body.tool_choice ?? null,
    tools: (body.tools ?? []).map((t: any) => t.function.name).sort(),
    messages: (body.messages as any[]).map((m, i) => ({
      role: m.role,
      kind: kindOf(m, i),
      keys: Object.keys(m).sort(),
      ...(m.tool_calls ? { tool_calls: m.tool_calls.map((c: any) => ({ id: ordinal(c.id), type: c.type, name: c.function.name })) } : {}),
      ...(m.tool_call_id ? { tool_call_id: ordinal(m.tool_call_id), name: m.name } : {}),
    })),
  };
}

function expectSnapshot(name: string, actual: unknown): void {
  const file = path.join(snapshotDir, `${name}.json`);
  const json = `${JSON.stringify(actual, null, 2)}\n`;
  if (process.env.NEXUS_UPDATE_SNAPSHOTS === "1") {
    fs.mkdirSync(snapshotDir, { recursive: true });
    fs.writeFileSync(file, json);
    return;
  }
  assert.ok(fs.existsSync(file), `missing snapshot ${file}; run with NEXUS_UPDATE_SNAPSHOTS=1`);
  assert.deepEqual(JSON.parse(JSON.stringify(actual)), JSON.parse(fs.readFileSync(file, "utf8")), `request shape ${name} changed; review and rerun with NEXUS_UPDATE_SNAPSHOTS=1 if intended`);
}

/** Nothing Nexus keeps for itself may reach the provider: no internal field on any message or the body. */
function assertNoInternalFields(bodies: any[]): void {
  for (const body of bodies) {
    assert.ok(!JSON.stringify(Object.keys(body)).match(/toolCallSource/), "toolCallSource is not a body key");
    for (const m of body.messages) {
      assert.deepEqual(Object.keys(m).filter((k) => !["role", "content", "tool_calls", "tool_call_id", "name"].includes(k)), [], `unexpected message key on ${m.role}`);
      assert.ok(!("toolCallSource" in m));
    }
    assert.doesNotMatch(JSON.stringify(body.messages), /toolCallSource/);
  }
}

function assertToolIdsPaired(body: any): void {
  const offered = new Set<string>();
  for (const m of body.messages) {
