  .action(async (promptParts: string[], _options: any, cmd: Command) => {
    const options = commandOptions(cmd);
    let prompt = promptParts.join(" ").trim();
    const config = buildConfig(options);
    config.surface = "headless";
    const outputFormat = String(options.output ?? (options.json ? "json" : "text"));
    if (!["text", "json", "stream-json"].includes(outputFormat) || (options.json && outputFormat !== "json")) {
      console.error(options.json && ["text", "stream-json"].includes(outputFormat) ? "error: --json cannot be combined with --output " + outputFormat : "error: --output must be text, json or stream-json");
      exitAfterFlush(2);
      return;
    }
    const isStream = outputFormat === "stream-json";
    // The event sink writes through the real stdout.write, captured before runTask intercepts stdout for machine output.
    const realStdoutWrite = process.stdout.write.bind(process.stdout);
    const emitEvent = isStream ? streamEventSink((chunk) => realStdoutWrite(chunk)) : undefined;
    const isJson = outputFormat !== "text";

    // Auto-detect loaded model if model is 'local-model' (not on a resume: the task record supplies it, or the first
    // step detects it after the resumed provider wait)
    if (config.model === "local-model" && (options.resume === undefined || options.resume === false)) {
      try {
        const client = new LocalLlmClient(config);
        const models = await client.listModels();
        if (models.length > 0) {
          config.model = models[0];
          if (!isJson) {
            console.log(pc.dim(`🔍 Auto-detected active model: ${pc.bold(config.model)}`));
          }
        }
      } catch {
        // Fallback to default
      }
    }

    if (!isJson && (config.provider || config.plannerProvider || config.coderProvider)) console.error(pc.dim(describeTarget(config)));
    const app = new ApplicationCore(config);

    let resumeTaskId: string | undefined;
    if ((options.resume === undefined || options.resume === false) && !prompt) {
      console.error("error: missing required argument 'prompt'");
      app.shutdown();
      exitAfterFlush(1);
      return;
    }

    // Operator stop authority: first SIGINT cancels the active turn; a second one terminates immediately.
    const abort = new AbortController();
    let sigints = 0;
    const onSigint = () => {
      sigints++;
      if (sigints === 1) {
        abort.abort(new Error("SIGINT"));
        if (!isJson) console.error(pc.yellow("\nInterrupt received: no further work will be started (Ctrl-C again to terminate immediately)."));
      } else {
        process.exit(130);
      }
    };
    process.on("SIGINT", onSigint);

    try {
      if (options.resume !== undefined && options.resume !== false) {
        if (typeof options.resume === "string" && options.resume !== "latest") {
          resumeTaskId = options.resume;
        } else {
          const targetWorkspace = config.workspace || process.cwd();
          const tasks = app
            .getStateManager()
            .listTasks({ workspace: targetWorkspace })
            .filter((t) => t.taskId !== app.getTaskId());
          if (tasks.length === 0) {
            console.error(`no task to resume in ${formatDiagnosticForOutput(targetWorkspace)}; see 'nexus status'`);
            app.shutdown();
            exitAfterFlush(2);
            return;
          }
          resumeTaskId = tasks[0].taskId;
        }
        if (!prompt) {
          prompt = options.step ? "" : "continue";
        }
      }
      emitEvent?.("start", { model: config.model, ...(config.provider ? { provider: config.provider } : {}) });
      const result = await app.runTask(prompt, {
        json: isJson,
        ...(emitEvent ? { observer: streamObserver(emitEvent) } : {}),
        resumeTaskId,
        signal: abort.signal,
        step: Boolean(options.step),
      });

      const cloud = UsageLedger.global().cloudTotals();
      if (emitEvent) {
        emitEvent("result", { ...(cloud.requests ? { ...result, cloudUsage: cloud } : result) });
      } else if (isJson) {
        console.log(JSON.stringify(cloud.requests ? { ...result, cloudUsage: cloud } : result, null, 2));
      } else if (cloud.requests) {
        console.error(pc.dim(UsageLedger.global().summary()!));
      }

      app.shutdown();
      exitAfterFlush(result.exitCode);
